package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	n, _ := strconv.Atoi(next())
	k, _ := strconv.Atoi(next())
	s := next()
	best := n + 1
	for first := 0; first < 2; first++ { // target 0101... or 1010...
		// end[i] toggles the flip parity when a window started at i-k stops covering i.
		end := make([]int, n+1)
		parity, count, possible := 0, 0, true
		for i := 0; i < n; i++ {
			parity ^= end[i]
			if (int(s[i]-'0') ^ parity) != (first ^ (i % 2)) {
				if i+k > n {
					possible = false
					break
				}
				parity ^= 1
				end[i+k] ^= 1
				count++
			}
		}
		if possible {
			best = min(best, count)
		}
	}
	if best > n {
		best = -1
	}
	fmt.Println(best)
}
